// =============================================================================
//  TIMELINE & PHYSICAL CONSTANTS
//  All state is a pure function of simTime (analytic / parametric model), so
//  forward play, reverse scrubbing and any display refresh rate agree exactly.
// =============================================================================
const DURATION = 8.000;
const SEED = 42;

const T_CONTACT = 1.000;   // bullet nose touches the latex
const T_PUNCT   = 1.120;   // latex punctures after elastic indentation
const T_SPREAD  = 0.140;   // tear runs around the circumference
const T_RUP     = 0.360;   // upper sheet retraction toward the tether
const T_RLOW    = 0.300;   // lower sheet retraction toward the base
const T_LDROP   = 1.560;   // lower latex cup detaches and falls away
const T_EXIT    = 3.800;   // bullet nose clears the left boundary
const GA = 4.30, GB = 5.60, G1 = 1.20;   // gravity ramp (camera speed-ramp)

const U_TOP = 0.955, U_BOT = 0.035;      // where retracted latex bunches up
const NECK_R = 0.07;
const Y_B_LOCAL = -0.20;                 // bullet latitude in balloon frame
const BALLOON_Y = -0.02;                 // balloon frame origin (world)
const LATEX_SCALE = 1.004, WATER_SCALE = 0.992;
const RB = 0.055, BULLET_LEN = 0.30;     // bullet radius / length
const AMAX = 0.25;                       // max cavitation tunnel radius
const X_START = 9.5, V_EXIT = 9.0;

// ---------------------------------------------------------------------------
const clamp = (x, a, b) => (x < a ? a : (x > b ? b : x));
const mix = (a, b, t) => a + (b - a) * t;
function smooth(e0, e1, x) {
  const t = clamp((x - e0) / (e1 - e0), 0, 1);
  return t * t * (3 - 2 * t);
}

// Deterministic PRNG (Mulberry32) - Math.random() is never used.
function mulberry32(a) {
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// =============================================================================
//  BALLOON PROFILE: teardrop curve with hydrostatic bottom sag.
//  u in [0,1]: 0 = bottom pole, 1 = tied neck.  Mirrored exactly in GLSL.
// =============================================================================
const PROF = { A: 1.0, B: 1.15, M: 0.9, TN: 0.3, SAG: 0.12 };
function profAt(th) {
  const rho = PROF.A * Math.sin(th) * Math.pow(Math.max(Math.sin(0.5 * th), 1e-4), PROF.M);
  let y = PROF.B * Math.cos(th);
  y -= PROF.SAG * Math.sin(th) * Math.sin(th) * smooth(1.0472, Math.PI, th);
  return [Math.max(rho, 0), y];
}
function profile(u) {
  return profAt(Math.PI + (PROF.TN - Math.PI) * clamp(u, 0, 1));
}
(function calibrateProfile() {
  let maxF = 0;
  for (let i = 1; i < 4000; i++) {
    const th = Math.PI * i / 4000;
    const f = Math.sin(th) * Math.pow(Math.sin(0.5 * th), PROF.M);
    if (f > maxF) maxF = f;
  }
  PROF.A = 1.0 / maxF;                     // widest radius = 1.0
  let lo = 0.01, hi = 1.5;
  for (let k = 0; k < 60; k++) {           // neck where radius = NECK_R
    const mid = 0.5 * (lo + hi);
    if (profAt(mid)[0] < NECK_R) lo = mid; else hi = mid;
  }
  PROF.TN = 0.5 * (lo + hi);
})();
const U_B = (function () {                 // material latitude of the impact
  let lo = 0, hi = 0.8;
  for (let k = 0; k < 60; k++) {
    const mid = 0.5 * (lo + hi);
    if (profile(mid)[1] < Y_B_LOCAL) lo = mid; else hi = mid;
  }
  return 0.5 * (lo + hi);
})();
const XR = profile(U_B)[0] * LATEX_SCALE;  // entry / exit boundary |x|
const NECK_Y = profile(1)[1] * LATEX_SCALE;
const BOTTOM_Y = profile(0)[1] * LATEX_SCALE;
