function profileNormal(u) {                // outward normal in (rho, y) plane
  const a = profile(u - 0.004), b = profile(u + 0.004);
  const tx = b[0] - a[0], ty = b[1] - a[1];
  const l = Math.hypot(tx, ty) || 1;
  return [ty / l, -tx / l];
