const D3 = D2 + 0.6 * 0.5 * (V_W1 + V_EXIT);

function easeDist(a, b, T, s) {
  return a * s + (b - a) * 0.5 * (s - (T / Math.PI) * Math.sin(Math.PI * s / T));
}
function easeVel(a, b, T, s) {
  return a + (b - a) * 0.5 * (1 - Math.cos(Math.PI * s / T));
}
function bulletDist(t) {
  if (t <= 0.7) return V_A * t;
  if (t <= 1.0) return V_A * 0.7 + easeDist(V_A, V_W0, 0.3, t - 0.7);
  if (t <= 3.8) { const s = t - 1.0; return D1 + V_W0 * s - 0.5 * DEC * s * s; }
