  PS.push(s); PL.push(life); PX.push(p[0]); PY.push(p[1]); PZ.push(p[2]);
  PVX.push(v[0]); PVY.push(v[1]); PVZ.push(v[2]); PK.push(k); PG.push(gs);
  PSZ.push(size); PA.push(a0); PKIND.push(kind); PST.push(st);
