  const s = openTime(a) + (0.04 + 0.8 * rng()) * T;
  const ue = memEdgeU(piece, a, s), ue2 = memEdgeU(piece, a, s + 0.01);
  const pr = profile(ue), pr2 = profile(ue2), n2 = profileNormal(ue);
