  const p = [pr[0] * ca * LATEX_SCALE, BALLOON_Y + pr[1] * LATEX_SCALE, pr[0] * sa * LATEX_SCALE];
  const evr = (pr2[0] - pr[0]) / 0.01, evy = (pr2[1] - pr[1]) / 0.01;
