  const s = 2.42 + 1.35 * Math.pow(rng(), 1.3);
  const aE = Math.max(cavityR(XR, s), 0.06);
  const th = rng() * TAU;
  const rr = aE * (0.7 + 0.35 * rng());
  const p = [XR + 0.02 + 0.03 * rng(), YB_WORLD + rr * Math.cos(th), rr * Math.sin(th)];
  const drop = rng() < 0.28;
  const ax = drop ? 0.5 + 1.2 * rng() : 0.8 + 2.0 * rng();
  const rad = drop ? 0.25 + 0.7 * rng() : 0.3 + 1.0 * rng();
