    const v = [
      (pB[0] - pC[0]) / (2 * h) + n2[0] * Math.cos(a) * 0.12 + jit * Math.sin(jph) * Math.cos(jth),
      (pB[1] - pC[1]) / (2 * h) + gF(tr) + n2[1] * 0.12 + jit * Math.cos(jph),
      (pB[2] - pC[2]) / (2 * h) + n2[0] * Math.sin(a) * 0.12 + jit * Math.sin(jph) * Math.sin(jth)
    ];
    const big = rng();
    const size = 0.018 + 0.05 * big * big;
    const lig = rng() < 0.35 ? 1.8 + 1.6 * rng() : 1;      // ligament before pinch-off
