const A_VX = Float64Array.from(PVX), A_VY = Float64Array.from(PVY), A_VZ = Float64Array.from(PVZ);
const A_K = Float64Array.from(PK), A_G = Float64Array.from(PG), A_SZ = Float64Array.from(PSZ);
const A_A = Float64Array.from(PA), A_KIND = Float64Array.from(PKIND), A_ST = Float64Array.from(PST);
const A_HS = new Float64Array(NP);
