const attrAlpha = new THREE.BufferAttribute(pAlpha, 1).setUsage(THREE.DynamicDrawUsage);
const attrDir = new THREE.BufferAttribute(pDir, 2).setUsage(THREE.DynamicDrawUsage);
const attrStr = new THREE.BufferAttribute(pStr, 1).setUsage(THREE.DynamicDrawUsage);
