const DENT_MAX = Math.max(0, XR - tipX(T_PUNCT));
function dentDepth(t) {                    // elastic indentation of the skin
  if (t < T_CONTACT) return 0;
  if (t <= T_PUNCT) return Math.max(0, XR - tipX(t));
  return DENT_MAX * Math.exp(-(t - T_PUNCT) / 0.05);
}
function knotRecoil(t) {                   // tether springs back once unloaded
  const tau = t - 4.5;
  if (tau <= 0) return 0;
  return 0.045 * (1 - Math.exp(-tau / 0.6) * Math.cos(6.0 * tau));
}

function renderAt(t) {
  t = clamp(t, 0, DURATION);
  const xt = tipX(t);

  // Bullet (rifling spin tied to distance travelled) + faint motion streak
  bulletGroup.position.set(xt + BULLET_LEN, YB_WORLD, 0);
  bulletMesh.rotation.x = -bulletDist(t) * 6.0;
  const sp = bulletSpeed(t);
  const sl = clamp(sp * 0.055, 0.001, 0.9);
  streak.scale.set(sl, RB * 1.5, 1);
  streak.position.set(xt + BULLET_LEN + sl * 0.5, YB_WORLD, 0);
  streakMat.uniforms.uStreakA.value = 0.32 * smooth(1.5, 6.0, sp);

  // Shared shader state
  U.uTime.value = t;
  U.uTipX.value = xt;
  U.uGate.value = cavGate(t);
  U.uCollapse.value = cavCollapse(t);
  U.uDent.value = dentDepth(t);
  U.uRipple.value = 0.010 * smooth(T_PUNCT, T_PUNCT + 0.06, t) * (1 - smooth(2.2, 3.2, t));
  U.uRipT.value = Math.max(0, t - T_PUNCT);
  U.uLip.value = 0.05 * smooth(T_PUNCT, 1.5, t) * (1 - smooth(2.0, 2.6, t))
               + 0.17 * smooth(2.45, 3.3, t) * (1 - smooth(4.4, 5.3, t));
  U.uDome.value = 0.13 * smooth(3.35, 3.83, t) * (1 - smooth(3.88, 4.4, t));
  U.uCone.value = 0.24 * smooth(3.82, 4.35, t) * (1 - smooth(4.8, 5.7, t));
  U.uExpand.value = bodyExpand(t);
  U.uDrift.value = bodyDrift(t);
  U.uFall.value = bodyFall(t);
  U.uFinger.value = 0.2 * smooth(4.7, 6.8, t);
  U.uAE.value = cavityR(XR, t);
  U.uAX.value = cavityR(-XR, t);

  // Latex remnants: lower cup tumbles away, upper collar hangs at the knot
  const tl = Math.max(0, t - T_LDROP);
  U.uLowOff.value.set(0.05 * tl, -0.45 * tl - gH(t));
  U.uLowRot.value = 0.55 * tl;
  U.uUpShrink.value = 1 - 0.45 * smooth(4.5, 5.9, t);
  const kdy = knotRecoil(t);
  U.uKnotDY.value = kdy;
  knotGroup.position.y = KNOT_BASE_Y + kdy;

  const wet = t >= T_PUNCT - 1e-4 && t < 7.25;
  waterBack.visible = wet;
  waterFront.visible = wet;
  cavMesh.visible = t >= T_PUNCT && t < 5.35;

  updateParticles(t);
  renderer.render(scene, camera);
}

