// =============================================================================
//  PLAYBACK STATE MACHINE: COUNTDOWN | PLAYING | PAUSED | REFIRE_HOLD | ENDED
// =============================================================================
const elCountdown = document.getElementById('countdown');
const elToggle = document.getElementById('btn-toggle');
const elRefire = document.getElementById('btn-refire');
const elIconPause = document.getElementById('icon-pause');
const elIconPlay = document.getElementById('icon-play');
const elScrub = document.getElementById('scrubber');
const pills = Array.prototype.slice.call(document.querySelectorAll('.speed-pill'));

const S_COUNTDOWN = 'COUNTDOWN', S_PLAYING = 'PLAYING', S_PAUSED = 'PAUSED',
      S_REFIRE_HOLD = 'REFIRE_HOLD', S_ENDED = 'ENDED';
let state = 'INIT';
let simTime = 0;
let playbackSpeed = 1.0;
let countdownStart = 0, countdownElapsed = 0;
let holdStart = 0, holdElapsed = 0;
let lastTs = null;

function showPauseIcon() {
  elIconPause.style.display = 'block';
  elIconPlay.style.display = 'none';
  elToggle.setAttribute('aria-label', 'Pause');
}
function showPlayIcon() {
  elIconPause.style.display = 'none';
  elIconPlay.style.display = 'block';
  elToggle.setAttribute('aria-label', 'Play');
}
function hideCountdown() {
  elCountdown.style.display = 'none';
  elCountdown.textContent = '';
}
function showCountdown(txt) {
  elCountdown.style.display = 'block';
  if (elCountdown.textContent !== txt) elCountdown.textContent = txt;
}

function frame(ts) {
  requestAnimationFrame(frame);
  if (lastTs === null) lastTs = ts;
  const dt = Math.min(Math.max(0, (ts - lastTs) / 1000), 0.1);   // clamp tab-switch jumps
  lastTs = ts;

  if (state === S_COUNTDOWN) {
    countdownElapsed = Math.max(0, (ts - countdownStart) / 1000);  // wall clock, speed-independent
    if (countdownElapsed >= 3.0) {
      hideCountdown();
      state = S_PLAYING;
      simTime = 0;
      elScrub.value = '0';
    } else {
      showCountdown(countdownElapsed < 1.0 ? '3' : (countdownElapsed < 2.0 ? '2' : '1'));
      simTime = 0;
      elScrub.value = '0';
    }
